from pathlib import Path
import json, html
root=Path(__file__).resolve().parents[1]
catalog=json.loads((root/'docs/pets/catalog.json').read_text(encoding='utf-8'))
index=json.loads((root/'docs/pets/art-index.json').read_text(encoding='utf-8'))
for p in catalog:
    p['sheet']='../../assets/resources/art/'+p['id']+('-battle-ref.png' if p['id'] in ['fox','bud','turtle'] else '-battle-v1.png')
    p['rects']=index['rects'][p['id']]
    entry=next((f for f in index['files'] if f['id']==p['id']),None)
    p['source']='../../'+entry['source'] if entry else p['sheet']
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>18 属性伙伴 · 美术与制作图鉴</title>
<style>*{box-sizing:border-box}body{margin:0;background:#edf3f5;color:#203748;font:16px/1.65 system-ui,"Microsoft Yahei",sans-serif}header,main{max-width:1280px;margin:auto;padding:28px}header{padding-top:42px}h1{font-size:32px;line-height:1.3;margin:5px 0 16px}h2{margin:8px 0;font-size:21px}p{margin:8px 0}.eyebrow{letter-spacing:3px;color:#678797;font-size:12px}.rules{padding:20px;background:white;border-radius:16px;box-shadow:0 4px 20px #17364208;margin:20px 0}.tags{display:flex;gap:10px;flex-wrap:wrap}.tag,button{border:0;border-radius:24px;background:#dfeaf0;padding:7px 14px;font:inherit;color:inherit}.boss .tag{background:#fae8bb;color:#865d17}.elite .tag{background:#e9def7;color:#705293}button{cursor:pointer}button.active{background:#264d64;color:white}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:22px}.pet{background:white;border:2px solid #e4ecef;border-radius:20px;padding:18px;overflow:hidden}.pet.boss{border-color:#e4c16e}.pet.elite{border-color:#bca3d8}.views{display:grid;grid-template-columns:1fr 1fr;gap:8px}.view{background:linear-gradient(#f4f8fa,#e6eef3);border-radius:12px;text-align:center;color:#688292;font-size:12px}.view canvas{display:block;width:100%;aspect-ratio:1}.detail{font-size:14px;color:#597283;min-height:48px}.stats{font-size:13px;padding:9px;background:#f0f5f7;border-radius:8px}.links{display:flex;gap:16px;font-size:13px;margin-top:10px}a{color:#286c94}footer{padding:24px;color:#607d8b}.hidden{display:none}@media(max-width:600px){header,main{padding:18px}.grid{grid-template-columns:1fr}h1{font-size:26px}}</style>
<header><div class="eyebrow">PM · CREATURE DICE · v0.4</div><h1>18 属性伙伴<br>美术与制作图鉴</h1><p>14 只普通宠物 · 2 只精英 · 2 只 BOSS。原有 3 只复用，新增 15 只均具备正背面战斗图。</p>
<div class="rules"><b>10 关出怪安排</b><p>1–4 关普通随机 → 第 5 关精英随机 → 6–9 关普通随机、数值提升 → 第 10 关 BOSS 随机。</p><p>普通体型小而圆润；精英体型较大、结构鲜明；BOSS 巨大且有角冠、宽翼或重甲。图鉴为了便于查阅采用同尺寸画框，游戏内按类别区分大小。</p><p>每只统一使用透明图、正面朝左下 / 背面朝右上、等比显示与脚底锚点。属性本轮用于分类和美术识别。</p><a href="制作规格.txt">制作与接入规格</a> · <a href="catalog.json">完整数据表</a> · <a href="https://sg.portal-pokemon.com/game/type-chart/">官方属性分类参考</a> · <a href="http://127.0.0.1:8780/">进入游戏</a></div>
<nav class="tags"><button class="active" data-filter="all">全部 18</button><button data-filter="normal">普通 14</button><button data-filter="elite">精英 2</button><button data-filter="boss">BOSS 2</button></nav></header><main class="grid" id="grid"></main>
<footer>图片由内置 image_gen 生成，源图与完整提示词按类别、属性和 ID 归档。游戏原图未被裁切覆盖；显示区域与脚底锚点独立记录。</footer>
<script>const pets=__CATALOG__;const rankNames={normal:'普通',elite:'精英',boss:'BOSS'};const jobs=[];for(const p of pets){const card=document.createElement('article');card.className='pet '+p.rank;card.dataset.rank=p.rank;card.innerHTML=`<div class="tags"><span class="tag">${p.type}</span><span class="tag">${rankNames[p.rank]}</span></div><h2>${p.name}</h2><div class="views"><div class="view"><canvas data-side="front" width="512" height="512"></canvas>敌方正面 · 头像 / 收藏</div><div class="view"><canvas data-side="back" width="512" height="512"></canvas>我方背面 · 战斗</div></div><p class="detail">${p.design}</p><div class="stats">基础生命 ${p.hp} · 伙伴点数 ${p.faces.join(' / ')}<br>ID：${p.id} · ${['fox','bud','turtle'].includes(p.id)?'复用已验收资源':'新增双视图 1536 × 1024'}</div><div class="links"><a href="${p.source}">查看源图</a><a href="${p.sheet}">游戏资源</a></div>`;document.querySelector('#grid').append(card);jobs.push(new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{for(const c of card.querySelectorAll('canvas')){const [x,y,w,h]=p.rects[c.dataset.side],scale=456/Math.max(w,h);c.getContext('2d').drawImage(image,x,y,w,h,(512-w*scale)/2,(512-h*scale)/2,w*scale,h*scale);}resolve();};image.onerror=reject;image.src=p.sheet;}));}Promise.all(jobs).then(()=>window.catalogReady=true).catch(()=>window.catalogError=true);for(const button of document.querySelectorAll('button[data-filter]'))button.onclick=()=>{for(const b of document.querySelectorAll('button'))b.classList.toggle('active',b===button);for(const c of document.querySelectorAll('.pet'))c.classList.toggle('hidden',button.dataset.filter!=='all'&&c.dataset.rank!==button.dataset.filter);};</script></html>'''
(root/'docs/pets/宠物图鉴.html').write_text(page.replace('__CATALOG__',json.dumps(catalog,ensure_ascii=False)),encoding='utf-8')
print('Catalog written with '+str(len(catalog))+' pets and '+str(len(catalog)*2)+' views.')
